            // they were part of the params map, and SqlExecutor hands the map
            // to NamedParameterJdbcTemplate, which does parse `:_offset` /
            // `:_limit` as parameter names — so a stored SQL body that pages
            // itself would break on "No value supplied" if we dropped them.
            // No such body exists in src/main/resources, but nexa_sql holds
            // runtime data, so restoring the pre-existing contract is the safe
            // side. They carry the normalised, clamped numbers, which also
            // means the ceiling applies to a self-paging SQL body.
            Map<String, Object> sqlParams = new LinkedHashMap<>(filters);
            sqlParams.put(PARAM_OFFSET, offset);
            sqlParams.put(PARAM_LIMIT, limit);
            return sqlExecutor.executeQuery(list.getSqlId(), sqlParams);
        }
