# Docker image publishing to GHCR (#65)
#
# Companion to the tag-triggered release workflow (#59). When a
# `v*.*.*` tag is pushed:
#   1. Builds the multi-stage Dockerfile from this repo.
#   2. Pushes the image to GitHub Container Registry
#      (ghcr.io/<owner>/nexabuilder) under three tags:
#         - <full-version>   (e.g. 1.5.0)
#         - <major.minor>    (e.g. 1.5)
#         - latest           (only for non-prerelease tags)
#
# Image inherits the auto-built version label from build/Dockerfile;
# K8s manifests in deploy/k8s/ reference `:1.5.0` etc, so just
# bumping the tag is enough to roll forward.

name: docker-publish

on:
  push:
    tags:
      - "v*.*.*"

concurrency:
  group: docker-publish-${{ github.ref }}
  cancel-in-progress: false

jobs:
  build-and-push:
    name: build + push ghcr
    runs-on: ubuntu-latest
    timeout-minutes: 40

    permissions:
      # Needed to push packages to GHCR under the repo owner.
      contents: read
      packages: write

    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Set up Docker Buildx
        uses: docker/setup-buildx-action@v3

      - name: Log in to GHCR
